    for u, v, w in edges:
        reverse[v].append(u)

    reaches_T = [False] * N
    reaches_T[T] = True
    queue = deque([T])
    while queue:
        v = queue.popleft()
        for u in reverse[v]:
            if not reaches_T[u]:
                reaches_T[u] = True
                queue.append(u)

    if not reaches_T[s]:
        return ("unreachable", None)

    relevant_edges = [
        (u, v, w) for u, v, w in edges
        if reaches_T[u] and reaches_T[v]
    ]

    dist = [None] * N
    dist[s] = 0

    for _ in range(N - 1):
        next_dist = dist.copy()
        changed = False
        for u, v, w in relevant_edges:
            if dist[u] is None:
                continue
            candidate = dist[u] + w
            if next_dist[v] is None or candidate < next_dist[v]:
                next_dist[v] = candidate
                changed = True
        dist = next_dist
        if not changed:
            return ("finite", dist[T])

    # Test round N using only distances from round N - 1.
    for u, v, w in relevant_edges:
        if dist[u] is None:
