The violated invariant is that every thread in a block must reach the same block barrier: here, only 70 of 96 threads reach `__syncthreads()`. Successful immediate launch checks do not establish execution correctness, and the divergent barrier makes behavior undefined—not a guarantee that every device hangs. The unready event is consistent with stalled execution, but does not by itself establish the cause.

Move the barrier outside the conditional. This complete example accepts `valid` from 0 through 96 and defines the empty sum as zero:

```cpp
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

static void check(cudaError_t err)
{
    if (err != cudaSuccess) {
        std::fprintf(stderr, "CUDA error: %s\n",
                     cudaGetErrorString(err));
        std::exit(EXIT_FAILURE);
    }
}

__global__ void sum_valid(const float* input, float* output, int valid)
{
    __shared__ float values[96];
    const unsigned int i = threadIdx.x;

    // Only valid inputs are read; every shared slot is initialized.
    values[i] = (i < static_cast<unsigned int>(valid))
                    ? input[i] : 0.0f;

    __syncthreads();

    if (i == 0) {
        float sum = 0.0f;
        for (int j = 0; j < valid; ++j) {
            sum += values[j];
        }
        *output = sum;
    }
}

// Requires input to contain at least valid device floats and output
// to contain one device float. Launches exactly one 96-thread block.
static void launch_sum(const float* input, float* output,
                       int valid, cudaStream_t stream)
{
    if (valid < 0 || valid > 96) {
        std::fprintf(stderr, "valid must be between 0 and 96\n");
        std::exit(EXIT_FAILURE);
    }
    sum_valid<<<1, 96, 0, stream>>>(input, output, valid);
    check(cudaGetLastError());
}

int main(int argc, char** argv)
{
    int valid = 70;
    if (argc > 2) {
        std::fprintf(stderr, "Usage: %s [valid: 0..96]\n", argv[0]);
        return EXIT_FAILURE;
    }
    if (argc == 2) {
        char* end = nullptr;
        const long parsed = std::strtol(argv[1], &end, 10);
        if (end == argv[1] || *end != '\0' ||
            parsed < 0 || parsed > 96) {
            std::fprintf(stderr, "valid must be between 0 and 96\n");
            return EXIT_FAILURE;
        }
        valid = static_cast<int>(parsed);
    }

    float input[96];
    for (float& value : input) value = 1.0f;
    float result = -1.0f;
    float* device_input = nullptr;
    float* device_output = nullptr;
    cudaStream_t stream;
    cudaEvent_t done;

    check(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
    check(cudaEventCreateWithFlags(&done, cudaEventDisableTiming));
    check(cudaMalloc(reinterpret_cast<void**>(&device_input),
                     sizeof(input)));
    check(cudaMalloc(reinterpret_cast<void**>(&device_output),
                     sizeof(float)));

    check(cudaMemcpy(device_input, input, sizeof(input),
                     cudaMemcpyHostToDevice));
    launch_sum(device_input, device_output, valid, stream);
    check(cudaEventRecord(done, stream));
    check(cudaEventSynchronize(done));
    check(cudaMemcpy(&result, device_output, sizeof(result),
                     cudaMemcpyDeviceToHost));

    std::printf("valid=%d, sum=%g\n", valid,
                static_cast<double>(result));
    const bool passed = result == static_cast<float>(valid);

    check(cudaFree(device_output));
    check(cudaFree(device_input));
    check(cudaEventDestroy(done));
    check(cudaStreamDestroy(stream));
    return passed ? EXIT_SUCCESS : EXIT_FAILURE;
}
```

Compile with `nvcc -std=c++17 sum_valid.cu -o sum_valid`; run `./sum_valid 70`, `./sum_valid 0`, or `./sum_valid 96`.

Synchronization proof: all 96 threads initialize distinct shared slots and unconditionally execute the same barrier exactly once. The barrier makes those writes visible to thread zero before it reads entries 0 through `valid - 1`; no other thread subsequently writes shared memory. Input reads occur only for indices below `valid`, and all shared indices are below 96. For `valid == 0`, no input is read and thread zero writes zero; the completion event follows the kernel in the same stream.

B’s `cudaStreamWaitEvent(B, E, 0)` references the first record of E—the most recent record when that wait was submitted. Recording E again does not retarget that wait; a subsequent event query observes the second record. P2 can therefore race with C1: there is no ordering between them.

A permitted execution is:
1. A executes P1, then completes E’s first record.
2. B’s wait is satisfied.
3. A executes P2 while B executes C1. Both access the same allocation, with P2 writing: this violates exclusive ownership and creates a data race.
4. A’s second event record is still pending, so querying E returns `cudaErrorNotReady`. That says nothing about whether C1 has finished.

Use two device slots, each with a ready event and a consumed event. I’m interpreting “save first use” as “safe first use”: skip the consumed-event wait until that slot has actually been consumed once.

```cpp
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

static void check(cudaError_t status)
{
    if (status != cudaSuccess) {
        std::fprintf(stderr, "CUDA error: %s\n",
                     cudaGetErrorString(status));
        std::exit(EXIT_FAILURE);
    }
}

__global__ void produce(int* slot, int value)
{
    *slot = value;
}

__global__ void consume(const int* slot, int* result)
{
    *result = *slot;
}

int main()
{
    constexpr int iterations = 8;
    cudaStream_t A, B;
    cudaEvent_t ready[2], consumed[2];
    int* slots[2] = {nullptr, nullptr};
    int* results = nullptr;
    bool used[2] = {false, false};

    check(cudaStreamCreateWithFlags(&A, cudaStreamNonBlocking));
    check(cudaStreamCreateWithFlags(&B, cudaStreamNonBlocking));
    check(cudaMalloc(reinterpret_cast<void**>(&results),
                     iterations * sizeof(int)));

    for (int s = 0; s < 2; ++s) {
        check(cudaMalloc(reinterpret_cast<void**>(&slots[s]),
                         sizeof(int)));
        check(cudaEventCreateWithFlags(&ready[s], cudaEventDisableTiming));
        check(cudaEventCreateWithFlags(&consumed[s], cudaEventDisableTiming));
    }

    for (int i = 0; i < iterations; ++i) {
        const int s = i % 2;

        // On reuse, acquire the slot only after its previous reader finishes.
        if (used[s]) {
            check(cudaStreamWaitEvent(A, consumed[s], 0));
        }

        produce<<<1, 1, 0, A>>>(slots[s], i + 1);
        check(cudaGetLastError());
        check(cudaEventRecord(ready[s], A));

        // This wait captures this iteration's ready-event record.
        check(cudaStreamWaitEvent(B, ready[s], 0));
        consume<<<1, 1, 0, B>>>(slots[s], results + i);
        check(cudaGetLastError());
        check(cudaEventRecord(consumed[s], B));
        used[s] = true;
    }

    // Final drain only: no host synchronization between iterations.
    check(cudaStreamSynchronize(A));
    check(cudaStreamSynchronize(B));

    int host_results[iterations];
    check(cudaMemcpy(host_results, results, sizeof(host_results),
                     cudaMemcpyDeviceToHost));
    bool passed = true;
    for (int i = 0; i < iterations; ++i) {
        if (host_results[i] != i + 1) {
            std::fprintf(stderr, "Incorrect result at iteration %d\n", i);
            passed = false;
        }
    }

    for (int s = 0; s < 2; ++s) {
        check(cudaEventDestroy(ready[s]));
        check(cudaEventDestroy(consumed[s]));
        check(cudaFree(slots[s]));
    }
    check(cudaFree(results));
    check(cudaStreamDestroy(A));
    check(cudaStreamDestroy(B));
    return passed ? EXIT_SUCCESS : EXIT_FAILURE;
}
```

Compile with `nvcc -std=c++17 ownership.cu -o ownership`, then run `./ownership` on a CUDA-capable GPU.

For each slot, the enforced order is producer → ready record → consumer → consumed record → next producer. Ownership passes from A to B after ready completes, and back to A after consumed completes. Every wait is submitted after the intended record and before that event’s next re-record, so event reuse preserves these dependencies. First use needs no consumed wait because there is no previous reader; all iteration dependencies are device-side, with no device-wide synchronization.

Both can commit at repeatable read: this is write skew. Updating different rows avoids a direct write–write conflict, but does not protect the shared invariant that at least one doctor remains on call.

Exact interleaving, initially Alice and Bob are both on call:
1. Alice begins a repeatable-read transaction and counts 2 on-call doctors, establishing her snapshot.
2. Bob begins a repeatable-read transaction and also counts 2, establishing his snapshot.
3. Alice updates only Alice’s row to off call.
4. Bob updates only Bob’s row to off call.
5. Alice commits; Bob commits. Neither updated a row updated by the other, so both updates can succeed. The final on-call count is 0.

Use PostgreSQL serializable isolation for every transaction performing this decision:

```sql
-- Run setup once in a fresh database/schema.
CREATE TABLE doctors (
    name text PRIMARY KEY,
    on_call boolean NOT NULL
);

INSERT INTO doctors (name, on_call)
VALUES ('Alice', true), ('Bob', true);

CREATE FUNCTION take_off_call(doctor_name text)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    on_call_count bigint;
BEGIN
    SELECT count(*) INTO on_call_count
    FROM doctors
    WHERE on_call;

    IF on_call_count > 1 THEN
        UPDATE doctors
        SET on_call = false
        WHERE name = doctor_name;
    END IF;
END;
$$;

-- Session A:
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT take_off_call('Alice');
COMMIT;

-- Session B, run concurrently with Session A:
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT take_off_call('Bob');
COMMIT;
```

If either session receives SQLSTATE `40001`, including at `COMMIT`, roll back if the transaction is still open and retry the entire transaction: start a new serializable transaction, recount, reconsider the condition, perform any resulting update, and commit. Do not retry just the failed statement or reuse the previous count; the retry needs a fresh snapshot. Bounded retries with backoff are reasonable, but exhausting retries must report failure rather than treat the operation as committed.

For correctness, PostgreSQL detects read–write dependencies even when the transactions update different rows: Alice’s count reads Bob’s on-call state, and Bob’s count reads Alice’s. Both deciding from the initial state and committing their updates would create a serialization cycle, so that outcome cannot successfully commit under serializable isolation. In any equivalent serial execution, the first transaction may reduce the count from 2 to 1; the second then sees 1 and does not update. Thus at least one doctor remains on call, provided all transactions that could violate the invariant follow this serializable protocol.

