    if (i == 0) {
        float sum = 0.0f;
        for (int j = 0; j < valid; ++j) {
            sum += values[j];
        }
        *output = sum;
    }
}

// input: at least valid readable device floats; may be null for zero.
// output: one writable device float, not overlapping input.
// Buffers must remain valid until the kernel completes.
static void launch_sum(const float* input, float* output,
                       int valid, cudaStream_t stream)
{
    if (valid < 0 || valid > 96) {
        std::fprintf(stderr, "valid must be between 0 and 96\n");
        std::exit(EXIT_FAILURE);
    }
    sum_valid<<<1, 96, 0, stream>>>(input, output, valid);
    check(cudaGetLastError());
}

int main(int argc, char** argv)
{
    int valid = 70;
    if (argc > 2) {
        std::fprintf(stderr, "Usage: %s [valid: 0..96]\n", argv[0]);
        return EXIT_FAILURE;
    }
    if (argc == 2) {
        char* end = nullptr;
        const long parsed = std::strtol(argv[1], &end, 10);
        if (end == argv[1] || *end != '\0' ||
            parsed < 0 || parsed > 96) {
            std::fprintf(stderr, "valid must be between 0 and 96\n");
            return EXIT_FAILURE;
        }
        valid = static_cast<int>(parsed);
    }

    float input[96];
    for (float& value : input) value = 1.0f;
    float result;
    float* device_input = nullptr;
    float* device_output = nullptr;
    cudaStream_t stream;
    cudaEvent_t done;

    check(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
    check(cudaEventCreateWithFlags(&done, cudaEventDisableTiming));
    check(cudaMalloc(reinterpret_cast<void**>(&device_input), sizeof(input)));
    check(cudaMalloc(reinterpret_cast<void**>(&device_output), sizeof(float)));
    check(cudaMemcpy(device_input, input, sizeof(input), cudaMemcpyHostToDevice));

    launch_sum(device_input, device_output, valid, stream);
    check(cudaEventRecord(done, stream));
    check(cudaEventSynchronize(done));
    check(cudaMemcpy(&result, device_output, sizeof(result), cudaMemcpyDeviceToHost));

    std::printf("valid=%d, sum=%g\n", valid, static_cast<double>(result));
    const bool passed = result == static_cast<float>(valid);

    check(cudaFree(device_output));
    check(cudaFree(device_input));
    check(cudaEventDestroy(done));
    check(cudaStreamDestroy(stream));
    return passed ? EXIT_SUCCESS : EXIT_FAILURE;
}
```

Save as `sum_valid.cu`, compile with `nvcc -std=c++17 sum_valid.cu -o sum_valid`, and run with an optional integer from 0 through 96. Every accepted value launches exactly one block of 96 threads, including zero; the host never initializes the device output.

B’s wait references the first record of E—the latest record when that wait was submitted. Re-recording E does not retarget the wait; the later query observes the second record. P2 can race with C1 because neither stream orders C1 before P2. I’m interpreting “weight” as “wait” and “save first use” as “safe first use.”

A permitted execution is:
1. The host submits P1, E’s first record, B’s wait and C1, then P2 and E’s second record.
2. P1 finishes, and E’s first record completes, satisfying B’s wait. C1 has not executed yet.
3. The host queries E while its second record is incomplete and receives `cudaErrorNotReady`.
4. P2 overwrites the allocation and finishes before C1 reads it. C1 can therefore read P2’s value instead of P1’s. Alternatively, their accesses may overlap.

Use two slots and enforce, for each slot, producer → ready → consumer → consumed → next producer. First use skips the consumed wait because there is no previous reader.

```cpp
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

static void check(cudaError_t status)
{
    if (status != cudaSuccess) {
        std::fprintf(stderr, "CUDA error: %s\n",
                     cudaGetErrorString(status));
        std::exit(EXIT_FAILURE);
    }
}

__global__ void produce(int* slot, int value)
{
    *slot = value;
}

__global__ void consume(const int* slot, int* result)
{
    *result = *slot;
}

int main()
{
    constexpr int iterations = 8;
    cudaStream_t A, B;
    cudaEvent_t ready[2], consumed[2];
    int* slots[2] = {nullptr, nullptr};
    int* results = nullptr;
    bool used[2] = {false, false};

    check(cudaStreamCreateWithFlags(&A, cudaStreamNonBlocking));
    check(cudaStreamCreateWithFlags(&B, cudaStreamNonBlocking));
    check(cudaMalloc(reinterpret_cast<void**>(&results),
                     iterations * sizeof(int)));

    for (int s = 0; s < 2; ++s) {
        check(cudaMalloc(reinterpret_cast<void**>(&slots[s]),
                         sizeof(int)));
        check(cudaEventCreateWithFlags(&ready[s],
                                       cudaEventDisableTiming));
        check(cudaEventCreateWithFlags(&consumed[s],
                                       cudaEventDisableTiming));
    }

    for (int i = 0; i < iterations; ++i) {
        const int s = i % 2;

        // First use needs no predecessor. Reuse waits for its reader.
        if (used[s]) {
            check(cudaStreamWaitEvent(A, consumed[s], 0));
        }

        produce<<<1, 1, 0, A>>>(slots[s], i + 1);
        check(cudaGetLastError());
        check(cudaEventRecord(ready[s], A));

        // Captures this iteration's ready record.
        check(cudaStreamWaitEvent(B, ready[s], 0));
        consume<<<1, 1, 0, B>>>(slots[s], results + i);
        check(cudaGetLastError());
        check(cudaEventRecord(consumed[s], B));
        used[s] = true;
    }

    // Final drain only; no device-wide synchronization.
    check(cudaStreamSynchronize(A));
    check(cudaStreamSynchronize(B));

    int host_results[iterations];
    check(cudaMemcpy(host_results, results, sizeof(host_results),
                     cudaMemcpyDeviceToHost));
    bool passed = true;
    for (int i = 0; i < iterations; ++i) {
        if (host_results[i] != i + 1) {
            std::fprintf(stderr, "Incorrect result at iteration %d\n", i);
            passed = false;
        }
    }

    for (int s = 0; s < 2; ++s) {
        check(cudaEventDestroy(ready[s]));
        check(cudaEventDestroy(consumed[s]));
        check(cudaFree(slots[s]));
    }
    check(cudaFree(results));
    check(cudaStreamDestroy(A));
    check(cudaStreamDestroy(B));
    return passed ? EXIT_SUCCESS : EXIT_FAILURE;
}
```

Compile with `nvcc -std=c++17 ownership.cu -o ownership` and run on a CUDA-capable GPU.

For iteration i, B’s ready wait is submitted after that iteration’s ready record and before any subsequent re-record, so its consumer reads only after its producer finishes. On slot reuse at i+2, A’s consumed wait captures iteration i’s consumed record before that event is re-recorded, so the overwrite starts only after the previous consumer finishes. These edges form an acyclic dependency chain, protect slot ownership without implicit stream dependencies, and require neither device-wide synchronization nor host synchronization between iterations; host synchronization occurs only during the final drain.

Both can commit at PostgreSQL repeatable read: this is write skew. Updating different rows avoids a direct write–write conflict, but does not protect the invariant that at least one doctor remains on call. I’m interpreting “uncall” as “on-call.”

Exact interleaving:
1. Alice begins a repeatable-read transaction and counts 2 on-call doctors, establishing her snapshot.
2. Bob begins a repeatable-read transaction and also counts 2, before either update commits.
3. Alice marks Alice off call. Her snapshot now shows Alice off and Bob on.
4. Bob marks Bob off call. His snapshot shows Alice on and Bob off.
5. Alice commits; the committed state is Alice off, Bob on.
6. Bob commits; the committed state is both off. Neither updated a row modified by the other, so there is no same-row update conflict to prevent both commits.

Here is executable SQL for a fresh schema, followed by transactions to run in separate sessions:

```sql
CREATE TABLE doctors (
    name text PRIMARY KEY,
    on_call boolean NOT NULL
);

INSERT INTO doctors (name, on_call)
VALUES ('Alice', true), ('Bob', true);

CREATE FUNCTION take_off_call(doctor_name text)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    on_call_count bigint;
BEGIN
    SELECT count(*) INTO on_call_count
    FROM doctors
    WHERE on_call;

    IF on_call_count > 1 THEN
        UPDATE doctors
        SET on_call = false
        WHERE name = doctor_name AND on_call;
    END IF;
END;
$$;

-- Session A:
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT take_off_call('Alice');
COMMIT;

-- Session B, concurrently:
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT take_off_call('Bob');
COMMIT;
```

On SQLSTATE `40001`, whether raised during the function or at commit, roll back and retry the entire transaction from a new `BEGIN`: recount, reevaluate the condition, perform any permitted update, and commit. Do not retry only the update or commit using the old count.

Correctness: assuming all operations that could remove an on-call doctor follow this protocol, committed serializable transactions are equivalent to a serial execution. Starting with two on-call doctors, the first successful removal leaves one; the next transaction sees one and makes no removal. PostgreSQL therefore cannot commit both conflicting removals from the two-doctor snapshots; at least one must fail serialization, and its fresh retry preserves the invariant.

```cpp
#include <cuda_runtime.h>

__device__ __forceinline__ float sum19(float value)
{
    const unsigned int rank =
        threadIdx.x + blockDim.x *
        (threadIdx.y + blockDim.y * threadIdx.z);
    const unsigned int lane = rank % 32u;
    constexpr unsigned int mask = 0x0007ffffu;

    float sum = value;
    for (int offset = 16; offset >= 1; offset >>= 1) {
        const unsigned int partner = lane + offset;
        const bool has_partner = partner < 19u;
        const int source = has_partner
            ? static_cast<int>(partner)
            : static_cast<int>(lane);

        const float other = __shfl_sync(mask, sum, source, 32);
        if (has_partner) {
            sum = sum + other;
        }
    }
    return __shfl_sync(mask, sum, 0, 32);
}
```

Yes. A caller with no partner still executes `__shfl_sync`, choosing itself as the source; it skips only the addition. Every caller executes all five reduction collectives and the final broadcast.

A lane with no partner chooses itself as the shuffle source, not the out-of-range partner. The exact original code is:

```cpp
const unsigned int partner = lane + offset;
const bool has_partner = partner < 19u;
const int source = has_partner
    ? static_cast<int>(partner)
    : static_cast<int>(lane);

const float other = __shfl_sync(mask, sum, source, 32);
if (has_partner) {
    sum = sum + other;
}
```

Every caller is a physical lane 0–18, so its own bit is set in `mask = 0x0007ffffu`. All nineteen callers execute this shuffle unconditionally with the same mask, making the self-source participating without assuming implicit lockstep.

For example, lane 18 at offset 16 computes `partner = 34`, so `has_partner` is false and `source = 18`. It receives its current `sum`, but skips the addition, leaving `sum` unchanged—not doubled. The same reasoning applies at every no-partner step. Finally, every caller reads lane 0’s completed sum through the original broadcast; that replaces the returned value rather than adding another contribution.
